pub fn rotate(mut a: Vec<i32>, offset: usize) -> Vec<i32> {
    // If the array is empty, there's nothing to do.
    if !a.is_empty() {
        // Compute a safe rotation amount within [0, a.len())
        let k = offset % a.len();
        // In-place left-rotate by k. This moves element i to (i - k) mod n,
        // which is equivalent to taking element at (i + k) mod n to position i.
        a.rotate_left(k);
    }
    a
}

